  const close=e.target.closest('[data-loan-close]');
  if(close){window.__mozeSelectedLoanId=null;renderLoans();return}
  const full=e.target.closest('[data-loan-full]');
  if(full){const id=window.__mozeSelectedLoanId,loan=(state.loans||[]).find(l=>String(l.id)===String(id));if(loan){const el=document.getElementById('loanPaymentAmount');if(el)el.value=loanOutstanding(loan)}}
  const findLoan=v=>(state.loans||[]).find(l=>String(l.id)===String(v));
  const payDel=e.target.closest('[data-loan-pay-del]');
  if(payDel){const loan=findLoan(window.__mozeSelectedLoanId),p=loan?.payments.find(x=>String(x.id)===String(payDel.dataset.loanPayDel));if(!loan||!p)return;const t=loan.historicalOnly?null:loanPaymentTx(loan,p);const txs=loan.historicalOnly?loanTxs(loan):t?[t]:[];if(!confirm(`刪除這筆${loanActionLabel(loanDirection(loan))}記錄？\n\n${p.date||''} ${money(p.amount)}\n帳戶餘額還原：${loanEffectText(txs)}${loan.historicalOnly?'\n\n這是匯入時建立的歷史記錄，會連同這筆借還款一起刪除。':''}${!loan.historicalOnly&&!t?'\n\n⚠️ 找不到對應的交易，只會刪除記錄，不會調整帳戶餘額。':''}`))return;const r=removeLoanPayment(loan,p);if(r.removedLoan)window.__mozeSelectedLoanId=null;await save();render();return}
  const del=e.target.closest('[data-loan-delete]');
  if(del){const loan=findLoan(del.dataset.loanDelete);if(!loan)return;const txs=loanTxs(loan);if(!confirm(`刪除「${loan.person||'未指定對象'}」的這筆${loanLabel(loanDirection(loan))}？\n\n會一併刪除 ${txs.length} 筆相關交易（借出／借入與所有收還款）。\n帳戶餘額還原：${loanEffectText(txs)}`))return;removeLoan(loan);window.__mozeSelectedLoanId=null;window.__mozeLoanEditId=null;await save();render();return}
  const resume=e.target.closest('[data-loan-resume]');
  if(resume){const loan=findLoan(resume.dataset.loanResume);if(!loan)return;loan.status='';refreshLoanStatus(loan);await save();render();return}
  const editBtn=e.target.closest('[data-loan-edit]');
  if(editBtn){window.__mozeLoanEditId=editBtn.dataset.loanEdit;renderLoans();return}
