// V26.21: recurring items marked auto (r.auto) post every period that is due (next <= today) when the
// app renders, up to 24 periods per item per run. Transaction ids are deterministic per period
// (recurringTxId), so two devices posting the same period produce the same record, never a duplicate.
function autoPostRecurring(today = isoDate(new Date())) {
  let n = 0;
  for (const r of (state?.recurring || [])) {
    if (!r?.auto || r.paused) continue;
    normRecurring(r);
    let guard = 0;
    while (!recurringEnded(r) && r.next <= today && guard < 24) { const before = r.seq; postRecurring(r); if (r.seq === before) break; n++; guard++; }
  }
  return n;
}
